insert into public.antibiotic_interactions (drug_id, with_ar, with_en, desc_ar, desc_en, severity, source_ids, sort, reviewed, deleted) values ('aztreonam', $q$الأمينوغليكوزيدات$q$, $q$Aminoglycosides$q$, $q$مراقبة الكلى عند الجمع، خاصة مع الجرعات العالية أو العلاج الطويل.$q$, $q$Monitor the kidneys when combined, especially with high doses or long treatment.$q$, 'moderate', '{77}', 10, false, false);
insert into public.antibiotic_interactions (drug_id, with_ar, with_en, desc_ar, desc_en, severity, source_ids, sort, reviewed, deleted) values ('aztreonam', $q$السيفوكسيتين والإيميبينيم$q$, $q$Cefoxitin and imipenem$q$, $q$قد تُحفز إنزيمات بيتا لاكتاماز في بعض الجراثيم فتُضعف الأزتريونام: لا يُجمعان.$q$, $q$May induce beta-lactamases in some bacteria and antagonise aztreonam: do not combine.$q$, 'moderate', '{77}', 20, false, false);
